const response = $input.first().json.output;

let jsonStr = response;
if (jsonStr.includes('```json')) {
  jsonStr = jsonStr.split('```json')[1].split('```')[0];
} else if (jsonStr.includes('```')) {
  jsonStr = jsonStr.split('```')[1].split('```')[0];
}

const parsed = JSON.parse(jsonStr.trim());

return [{
  json: {
    validazione: parsed.validazione,
    indice_validato: parsed.indice_validato,
    brief_capitoli: parsed.brief_capitoli,
    n_capitoli: parsed.brief_capitoli.length
  }
}];

const items = $('Code in JavaScript').first().json.brief_capitoli;

return items.map(item => ({
  json: item
}));
